package Task05;
import java.math.BigDecimal; import java.sql.*;
public class WalletTransfer { public static void transfer(Connection c,int from,int to,BigDecimal amount)throws SQLException {boolean old=c.getAutoCommit();c.setAutoCommit(false);try{try(PreparedStatement d=c.prepareStatement("UPDATE wallets SET balance=balance-? WHERE wallet_id=? AND balance>=?")){d.setBigDecimal(1,amount);d.setInt(2,from);d.setBigDecimal(3,amount);if(d.executeUpdate()!=1)throw new SQLException("Insufficient funds or source wallet missing");}try(PreparedStatement cr=c.prepareStatement("UPDATE wallets SET balance=balance+? WHERE wallet_id=?")){cr.setBigDecimal(1,amount);cr.setInt(2,to);if(cr.executeUpdate()!=1)throw new SQLException("Destination wallet missing");}c.commit();}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(old);}} }
